import datetime
import sys

from taf.ul.sc.util.scp import Scp


class Util(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def upload_files(self, local_dir, local_file, remote_device_name, remote_dir, timeout=20,
                     local_device_name='UnixLocal', remove_source_file=False, log_level='warning', port=22, hops=[],
                     new_file_name=None, autogenerate_hops=False):
        r"""
        SCP files from UnixLocal device (local_dir, local_file) to remote device (remote_dir)

        :param local_dir: directory of the local file
        :param local_file: Name of file or files separated comma for eg file1.txt,file2.txt. You could use also regex:
        r'/^((HWF|SCFC_\d+)\.xml|swconfig.txt)$/' - regex need to be put between //
        'HWF.xml,SCFC_*.xml,swconfig.txt'
        :param remote_device_name: name of the destination device
        :param remote_dir: directory on the destination device
        :param timeout: scp timeout is seconds
        :param local_device_name: name of the source device
        :param remove_source_file: True if source file should be removed after upload, False otherwise
        :param log_level: info, warning or error
        :param port: port for scp connection
        :param new_file_name: If you would like scp file with new name. Works only for single file
        :param hops: list of device hops between local_device_name and remote_device_name.
        :param autogenerate_hops: If device has defined PROXY_PC inside configuration - it wil be automatically added
                                  to the hops table
        :return: None
        """
        scp_obj = Scp(local_dir=local_dir, source_file=local_file, remote_device_name=remote_device_name,
                      remote_dir=remote_dir, timeout=timeout, local_device_name=local_device_name,
                      remove_source_file=remove_source_file, log_level=log_level, port=port, hops=hops,
                      new_file_name=new_file_name, autogenerate_hops=autogenerate_hops)
        scp_obj.upload()

    def download_files(self, local_dir, remote_file, remote_device_name, remote_dir, timeout=20,
                       local_device_name='UnixLocal', remove_source_file=False, log_level='warning', port=22, hops=[],
                       new_file_name=None, autogenerate_hops=False):
        r"""
        SCP files from Remote device (remote_dir, remote_file) to UnixLocal device (local_dir)

        :param local_dir: directory of the local file
        :param remote_file: Name of file or files separated comma for eg file1.txt,file2.txt. You could use also regex:
        r'/^((HWF|SCFC_\d+)\.xml|swconfig.txt)$/' - regex need to be put between //
        'HWF.xml,SCFC_*.xml,swconfig.txt'
        :param remote_device_name: name of the destination device
        :param remote_dir: directory on the destination device
        :param timeout: scp timeout is seconds
        :param local_device_name: name of the source device
        :param remove_source_file: True if source file should be removed after upload, False otherwise
        :param log_level: info, warning or error
        :param port: port for scp connection
        :param new_file_name: If you would like scp file with new name. Works only for single file
        :param hops: list of device hops between local_device_name and remote_device_name.
        :param autogenerate_hops: If device has defined PROXY_PC inside configuration - it wil be automatically added
                                  to the hops table
        :return: None
        """
        scp_obj = Scp(local_dir=local_dir, source_file=remote_file, remote_device_name=remote_device_name,
                      remote_dir=remote_dir, timeout=timeout, local_device_name=local_device_name,
                      remove_source_file=remove_source_file, log_level=log_level, port=port, hops=hops,
                      new_file_name=new_file_name, autogenerate_hops=autogenerate_hops)
        scp_obj.download()

    def test_log(self, msg, log_hierarchy=1, msg_prefix='>'):
        """
        Print formatted logs on the console so that user can know test progress clearly.

        :param msg: str, to be output on the console with timestamp
        :param log_hierarchy: int, to determine how to display log, e.g,
                ...
                [ 2019-09-03 20:12:34 ] > some message
                [ 2019-09-03 20:12:35 ] >> other message
                ...
        :param msg_prefix: str, work as indicator of log hierarchy. Default is '>'.
        :return: None
        """
        msg_time = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        sys.__stdout__.write('\r[{}] {} {}\n'.format(msg_time, msg_prefix * int(log_hierarchy), msg))
